start transaction;
CREATE TABLE IF NOT EXISTS "private"."messages"(id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY, chat_id bigint NOT NULL REFERENCES "public"."chats"(id),"from" varchar(36) NOT NULL REFERENCES "keycloak".user_entity(id), "to" varchar(36) NOT NULL REFERENCES "keycloak".user_entity(id), encrypted_message varchar(500) NOT NULL, created_at timestamp NOT NULL DEFAULT now(), modified_at timestamp NULL, deleted_for_all bool default false, deleted_for_author_only bool default false);
commit;